// AddFriendParams 直接添加好友（双方同时成为好友）的参数（Friends.Add）。
type AddFriendParams struct {
	// 备注，只设置 {username} 一侧；去掉首尾空白后最长 64 个字符，不能含控制字符；空字符串为没有备注
	Remark string
	// 自定义属性，只设置 {username} 一侧；最多 16 个键（1 到 32 个 [A-Za-z0-9_.-]）、合计 1 KB；已是好友时按项合并，null 清空全部，某一项为 null 删除这一项；三种状态：零值不发送，Null 发送 null，Set 发送值
	Attributes Field[map[string]Field[string]]
	// 添加来源，双方相同；最长 32 个 [A-Za-z0-9_.:-]；已是好友时忽略
	AddSource string
	// 成为好友的时间，不能晚于当前时间，用于迁移时保留原来的时间；不给为当前时间，已是好友时忽略
	CreatedAt time.Time
}

// UpdateFriendParams 修改好友的备注和自定义属性的参数（Friends.Update）。
type UpdateFriendParams struct {
	// 去掉首尾空白后最长 64 个字符，不能含控制字符；空字符串清空
	Remark *string
	// null 清空全部；按项合并，某一项为 null 删除这一项；合并后最多 16 个键、合计 1 KB；三种状态：零值不发送，Null 发送 null，Set 发送值
	Attributes Field[map[string]Field[string]]
}

