// Mentions 只用于群聊；不是群成员的用户名被忽略
type Mentions struct {
	// 被 @ 的用户名，最多 20 个
	Usernames []string
	// 是否 @ 全体成员
	All bool
}

func encMentions(w *jw, v Mentions) {
	w.maxItems("usernames", len(v.Usernames), 20)
	w.beginObject()
	if v.Usernames != nil {
		w.key("usernames")
		encSlice(encStr)(w, v.Usernames)
	}
	if v.All {
		w.key("all")
		encBool(w, v.All)
	}
	w.endObject()
}

// ReplyTo ReplyTo
type ReplyTo struct {
	// 被引用消息在同一会话中的序号；必须存在、在保留期内、没有撤回或擦除，且发送者能看到（必填）
	Seq int64
}

func encReplyTo(w *jw, v ReplyTo) {
	w.beginObject()
	w.key("seq")
	encInt64(w, v.Seq)
	w.endObject()
}

// MessagePushOptions 消息的离线推送选项（《推送/3.接口设计》第 10.1 节），整个对象按紧凑 JSON 不超过 2 KB；不符合的为 invalid_argument
// （invalid_push，details.field 指出字段）。
type MessagePushOptions struct {
	// 不发离线推送
	Disabled bool
	// 不受接收者免打扰的限制；不能与 disabled 同时为真，对不计入未读的消息无效
	Force bool
	// 通知的标题，1 到 64 个字符，不能有控制字符；不给时按模板生成
	Title string
	// 通知的正文，1 到 256 个字符，不能有控制字符；不给时按模板生成
	Body string
	// 随通知交给 App 的 JSON 对象，紧凑编码后最多 512 字节
	Ext json.RawMessage
}

func encMessagePushOptions(w *jw, v MessagePushOptions) {
	w.beginObject()
	if v.Disabled {
		w.key("disabled")
		encBool(w, v.Disabled)
	}
	if v.Force {
		w.key("force")
		encBool(w, v.Force)
	}
	if v.Title != "" {
		w.key("title")
		encStr(w, v.Title)
	}
	if v.Body != "" {
		w.key("body")
		encStr(w, v.Body)
	}
	if v.Ext != nil {
		w.key("ext")
		encObject(w, v.Ext)
	}
	w.endObject()
}

// ModerationSceneUpdate ModerationSceneUpdate
type ModerationSceneUpdate struct {
	// 是否启用租户规则
	Enabled *bool
	// async 只能用于 message、chatroom_message；media_upload 只能为 off
	TextProvider *string
	// sync 只能用于 user_profile、group_profile；async 只能用于 message、chatroom_message、media_upload
	MediaProvider *string
	// 是否检查服务端提交的内容；chatroom_attribute 不能开启
	IncludeServerSent *bool
}

func encModerationSceneUpdate(w *jw, v ModerationSceneUpdate) {
	w.beginObject()
	if v.Enabled != nil {
		w.key("enabled")
		encBool(w, *v.Enabled)
	}
	if v.TextProvider != nil {
		w.key("text_provider")
		encStr(w, *v.TextProvider)
	}
	if v.MediaProvider != nil {
		w.key("media_provider")
		encStr(w, *v.MediaProvider)
	}
	if v.IncludeServerSent != nil {
		w.key("include_server_sent")
		encBool(w, *v.IncludeServerSent)
	}
	w.endObject()
}

