// ModerationActionInput 结论中选择的一个处置
type ModerationActionInput struct {
	// 必填
	Kind string
	// mute_user 必填
	Scopes []string
	// mute_user、disable_user 的时长，不给为永久
	DurationSeconds *int64
	// clear_profile 清除的字段，不给为快照中的全部
	Fields []string
	// block_file 的文件，不给为消息中全部本应用的文件
	FileIDs []string
}

func encModerationActionInput(w *jw, v ModerationActionInput) {
	w.require(v.Kind != "", "kind")
	w.beginObject()
	w.key("kind")
	encStr(w, v.Kind)
	if v.Scopes != nil {
		w.key("scopes")
		encSlice(encStr)(w, v.Scopes)
	}
	if v.DurationSeconds != nil {
		w.key("duration_seconds")
		encInt64(w, *v.DurationSeconds)
	}
	if v.Fields != nil {
		w.key("fields")
		encSlice(encStr)(w, v.Fields)
	}
	if v.FileIDs != nil {
		w.key("file_ids")
		encSlice(encStr)(w, v.FileIDs)
	}
	w.endObject()
}

