// CreateUserParams 创建用户的参数（批量创建的每一项相同）
type CreateUserParams struct {
	// 1 到 64 个 [A-Za-z0-9_.-]，不能是 . 或 ..（必填）
	Username string
	// 1 到 64 个字符；不给时只能用登录凭证登录
	Password string
	// 最长 64 个字符
	Nickname string
	// 最长 512 字节的 http(s) 地址
	AvatarURL string
	// 最多 32 个键、合计 4 KB
	Attributes map[string]string
}

func encCreateUserParams(w *jw, v CreateUserParams) {
	w.require(v.Username != "", "username")
	w.beginObject()
	w.key("username")
	encStr(w, v.Username)
	if v.Password != "" {
		w.key("password")
		encStr(w, v.Password)
	}
	if v.Nickname != "" {
		w.key("nickname")
		encStr(w, v.Nickname)
	}
	if v.AvatarURL != "" {
		w.key("avatar_url")
		encStr(w, v.AvatarURL)
	}
	if v.Attributes != nil {
		w.key("attributes")
		encMap(encStr)(w, v.Attributes)
	}
	w.endObject()
}

// AddFriendItem 批量添加好友的一项（字段的规则与单个添加相同）
type AddFriendItem struct {
	// 对方的用户名（必填）
	Username string
	// 备注，只设置所有者一侧；去掉首尾空白后最长 64 个字符，不能含控制字符
	Remark string
	// 自定义属性，只设置所有者一侧；最多 16 个键（1 到 32 个 [A-Za-z0-9_.-]）、合计 1 KB；已是好友时按项合并，null 清空全部，某一项为 null 删除这一项；三种状态：零值不发送，Null 发送 null，Set 发送值
	Attributes Field[map[string]Field[string]]
	// 添加来源，双方相同；最长 32 个 [A-Za-z0-9_.:-]；已是好友时忽略
	AddSource string
	// 成为好友的时间，不能晚于当前时间；不给为当前时间，已是好友时忽略
	CreatedAt time.Time
}

func encAddFriendItem(w *jw, v AddFriendItem) {
	w.require(v.Username != "", "username")
	w.beginObject()
	w.key("username")
	encStr(w, v.Username)
	if v.Remark != "" {
		w.key("remark")
		encStr(w, v.Remark)
	}
	writeField(w, "attributes", v.Attributes, encFieldMap(encStr))
	if v.AddSource != "" {
		w.key("add_source")
		encStr(w, v.AddSource)
	}
	if !v.CreatedAt.IsZero() {
		w.key("created_at")
		encTime(w, v.CreatedAt)
	}
	w.endObject()
}

// DND 全局免打扰：null 关闭；对象为开启
type DND struct {
	// 开启的时长（秒）；不给为一直开启
	DurationSeconds *int64
}

func encDND(w *jw, v DND) {
	w.beginObject()
	if v.DurationSeconds != nil {
		w.key("duration_seconds")
		encInt64(w, *v.DurationSeconds)
	}
	w.endObject()
}

// QuietHours 夜间免打扰：null 关闭
type QuietHours struct {
	// 开始的时刻，HH:MM（24 小时制，两位数）（必填）
	Start string
	// 结束的时刻，HH:MM；不能等于 start，早于 start 表示跨过午夜（必填）
	End string
	// IANA 时区名称，如 Asia/Shanghai（必填）
	Timezone string
}

func encQuietHours(w *jw, v QuietHours) {
	w.require(v.Start != "", "start")
	w.require(v.End != "", "end")
	w.require(v.Timezone != "", "timezone")
	w.beginObject()
	w.key("start")
	encStr(w, v.Start)
	w.key("end")
	encStr(w, v.End)
	w.key("timezone")
	encStr(w, v.Timezone)
	w.endObject()
}
